select date_trunc('quarter', opened_date) as quarter_start, date_trunc('week', opened_date) as week_start, stddev_samp(balance) as balance_stddev, count(distinct account_type) as distinct_account_types, approx_percentile(balance, 0.95) as balance_p95, sum(case when status = 'OPEN' then balance else 0 end) as open_balance from accounts group by date_trunc('quarter', opened_date), date_trunc('week', opened_date) having stddev_samp(balance) < 1000000;
